(async () => {
  const { readFileSync } = await import('node:fs');
  const csvPath = process.env.CSV_PATH;
  if (!csvPath) {
    throw new Error('Missing required env var CSV_PATH');
  }
  const content = readFileSync(csvPath, 'utf8');
  globalThis.csvContent = content;
})();

(async () => {
  const { parse } = await import('csv-parse');
  const content = globalThis.csvContent;
  if (typeof content !== 'string') {
    throw new Error('csvContent not set');
  }
  const records = await new Promise((resolve, reject) => {
    parse(content, { relax_column_count: true }, (err, output) => {
      if (err) reject(err);
      else resolve(output);
    });
  });
  globalThis.records = records;
})();

(async () => {
  const records = globalThis.records;
  if (!Array.isArray(records) || records.length === 0) {
    throw new Error('No records parsed');
  }
  const header = records[0];
  const rows = records.slice(1);
  const escape = (s) => String(s).replace(/\\|\|/g, '\\|');
  const makeRow = (row) => '| ' + row.map(escape).join(' | ') + ' |';
  const separator = '| ' + header.map(() => '---').join(' | ') + ' |';
  const markdown = [makeRow(header), separator, ...rows.map(makeRow)].join('\n');
  console.log(JSON.stringify({ markdown }));
})();
